<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderOidcClaimMappingAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderOidcClaimMappingAccessor trait.
 *
 * Covers null default, string/VO assignment via withOidcClaimMapping,
 * getOidcClaimMapping/oidcClaimMapping accessors, and isOidcClaimMappingChanged with/without original.
 */
class TenantLoginProviderOidcClaimMappingAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withOidcClaimMapping creates a new instance with the OidcClaimMapping set
     * from a string value, and getOidcClaimMapping returns the primitive string.
     */
    public function testWithOidcClaimMappingFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcClaimMappingAccessorUnitTest();

        // Act
        $result = $holder->withOidcClaimMapping('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getOidcClaimMapping());
    }
    /**
     * Asserts that withoidcClaimMapping has access to the value object
     * from a string value, and getOidcClaimMapping returns the primitive string.
     */
    public function testWithOidcClaimMappingFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcClaimMappingAccessorUnitTest();

        // Act
        $result = $holder->withOidcClaimMapping('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->oidcClaimMapping()->value());
    }
    public function testChangedOidcClaimMapping(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcClaimMappingAccessorUnitTest();
        $original = $holder->withOidcClaimMapping('one');
        $same = $holder->withOidcClaimMapping('one');
        $modified = $holder->withOidcClaimMapping('other');

        // Act
        $unchanged = $holder->isOidcClaimMappingChanged();
        $withSame = $original->isOidcClaimMappingChanged($same);
        $withDiferent = $original->isOidcClaimMappingChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderOidcClaimMappingAccessorUnitTest
{
    use TenantLoginProviderOidcClaimMappingAccessor;
}
